SELECT 
FROM appointment_waitlist waitlist
INNER JOIN doctor_schedule_slot slot ON slot.id = waitlist.schedule_slot_id
WHERE waitlist.id = #{id}
  AND waitlist.patient_id = #{patientId}

SELECT 


    AND waitlist.status = #{status}
    AND slot.schedule_date = #{scheduleDate}

        AND slot.doctor_id IN

            #{doctorId}



        AND waitlist.patient_id IN

            #{patientId}



ORDER BY waitlist.created_at DESC, waitlist.id DESC
